from collections import deque

def controller(obs, memory):
    """
    Refined staged controller for the 6-room chain task.

    Signature: controller(obs, memory) -> int
    Actions: 0 turn_left, 1 turn_right, 2 forward, 3 pickup, 4 drop, 5 toggle, 6 done

    Improvements over previous version:
    - Detects when a forward was executed but did not change the view (i.e. forward was blocked).
      In that case it avoids issuing forward again and instead turns to escape the obstacle.
    - Avoids forwarding into walls/closed/locked doors.
    - Alternates turning when stuck to escape local loops.
    - Keeps lightweight fingerprints to detect repeats and adjusts scan direction.
    """

    # --- utility accessors ---
    image = obs.get('image')
    last_executed = obs.get('last_action')

    if image is None:
        return 6

    def cell_at(col, row):
        if not (0 <= col < 7 and 0 <= row < 7):
            return [0, 0, 0]
        try:
            return image[col][row]
        except Exception:
            return [0, 0, 0]

    front = cell_at(3, 5)
    carried = cell_at(3, 6)  # carried object (object==1 => nothing carried)

    # --- memory initialization ---
    memory.setdefault('phase', 1)
    memory.setdefault('scan_dir', 1)        # preferred scan direction: 1 -> right, 0 -> left
    memory.setdefault('last_turn', None)    # last executed turn action (0 or 1) observed via obs['last_action']
    memory.setdefault('views', deque(maxlen=16))
    memory.setdefault('last_view', None)    # previous fingerprint
    memory.setdefault('failed_forwards', 0) # count of recent forwards that resulted in no observable progress
    memory.setdefault('repeat_count', 0)

    # --- record last executed turn into memory (we must trust obs['last_action']) ---
    if last_executed in (0, 1):
        memory['last_turn'] = last_executed

    # --- fingerprint current view to detect movement/repeats ---
    def view_fingerprint():
        # compact signature: column 3 rows 0..6 + immediate left/right near agent + carried
        key = []
        for r in range(7):
            c = cell_at(3, r)
            key.append((c[0], c[1], c[2]))
        key.append(tuple(cell_at(2, 5)))
        key.append(tuple(cell_at(4, 5)))
        key.append(tuple(carried))
        return tuple(key)

    vf = view_fingerprint()
    prev_vf = memory.get('last_view')

    # Update failed_forwards: if last executed was forward but view didn't change -> forward was blocked
    if last_executed == 2 and prev_vf is not None and prev_vf == vf:
        memory['failed_forwards'] += 1
    else:
        # small decay / reset whenever we observe a change or the last action wasn't forward
        memory['failed_forwards'] = max(0, memory['failed_forwards'] - 1)

    # record view history
    memory['views'].append(vf)
    if memory['views'].count(vf) > 4:
        memory['repeat_count'] += 1
    else:
        memory['repeat_count'] = max(0, memory['repeat_count'] - 1)

    # If we see the goal anywhere, switch to final phase
    def find_any(obj_id):
        for i in range(7):
            for j in range(7):
                c = cell_at(i, j)
                if c[0] == obj_id:
                    return (i, j, c)
        return (None, None, None)

    def find_first_in_col3(obj_id):
        for j in range(7):
            c = cell_at(3, j)
            if c[0] == obj_id:
                return (3, j, c)
        return (None, None, None)

    goal_pos = find_any(8)[0:2]
    if goal_pos[0] is not None:
        memory['phase'] = 6

    phase = memory['phase']

    # --- helpers ---
    def is_pickable(cell):
        return cell[0] in (5, 6, 7)
    def carrying_key_of_color(col):
        return carried[0] == 5 and carried[1] == col

    # --- safety: never forward into unseen or blocking cells ---
    # Allowed forward only if:
    # - goal (8)
    # - empty (1) or floor (3)
    # - door (4) with state 0 (open)
    def front_allows_forward(cell):
        if cell[0] == 8:
            return True
        if cell[0] in (1, 3):
            return True
        if cell[0] == 4 and cell[2] == 0:
            return True
        return False

    # If front is unseen, scan by turning (prefer scan_dir), but flip if repeat_count high
    if front[0] == 0:
        if memory['repeat_count'] >= 4:
            memory['scan_dir'] = 1 - memory['scan_dir']
            memory['repeat_count'] = 0
            # perform immediate turn in new scan direction
            return 1 if memory['scan_dir'] == 1 else 0
        # avoid turning the same way repeatedly: if last_turn equals scan_dir, try opposite
        desired = 1 if memory['scan_dir'] == 1 else 0
        if memory['last_turn'] == desired:
            memory['scan_dir'] = 1 - memory['scan_dir']
            desired = 1 if memory['scan_dir'] == 1 else 0
        return desired

    # --- door handling when directly in front ---
    if front[0] == 4:
        door_state = front[2]
        door_color = front[1]
        if door_state == 0:
            # open door: only forward if allowed and we aren't detecting failed forwards
            if memory['failed_forwards'] > 0:
                # a previous forward didn't move us; prefer turning to re-orient
                if memory['last_turn'] == 1:
                    return 0
                else:
                    return 1
            return 2
        elif door_state == 1:
            return 5
        else:  # locked
            if carrying_key_of_color(door_color):
                return 5
            # look for key; if none visible, scan/turn
            kcol, krow, _ = find_any(5)
            if kcol is not None:
                # try to face the key
                if kcol < 3:
                    return 0
                elif kcol > 3:
                    return 1
                else:
                    # key is ahead but unreachable due to locked door -> scan
                    return 1 if memory['scan_dir'] == 1 else 0
            return 1 if memory['scan_dir'] == 1 else 0

    # --- if front is goal -> move forward ---
    if front[0] == 8:
        return 2

    # --- if front is wall, avoid forwarding: choose a turn away from last_turn ---
    if front[0] == 2:
        # If we recently tried to forward and failed, definitely turn the opposite way to escape
        if memory['failed_forwards'] > 0:
            if memory['last_turn'] == 1:
                return 0
            elif memory['last_turn'] == 0:
                return 1
            else:
                # prefer left initially
                return 0
        # Otherwise, choose turn that alternates from last_turn to avoid oscillation
        if memory['last_turn'] == 1:
            return 0
        elif memory['last_turn'] == 0:
            return 1
        else:
            return 1 if memory['scan_dir'] == 1 else 0

    # --- pickable in front: pick keys when empty-handed, otherwise avoid picking extraneous objects ---
    if front[0] == 5 and carried[0] == 1:
        return 3
    if front[0] in (6, 7):
        # avoid picking non-key objects; turn to find another path
        # pick only if we are completely stuck (failed_forwards large)
        if memory['failed_forwards'] >= 3 and carried[0] == 1:
            return 3
        return 1 if memory['scan_dir'] == 1 else 0

    # --- default: forward if allowed and we are not in a failed-forward situation ---
    if front_allows_forward(front) and memory['failed_forwards'] == 0:
        return 2

    # If forward would be allowed but we have evidence previous forwards failed, turn to escape
    if front_allows_forward(front) and memory['failed_forwards'] > 0:
        if memory['last_turn'] == 1:
            return 0
        else:
            return 1

    # Final fallback: scan/turn (alternate directions if repeating)
    if memory['repeat_count'] >= 4:
        memory['scan_dir'] = 1 - memory['scan_dir']
        memory['repeat_count'] = 0
    return 1 if memory['scan_dir'] == 1 else 0

    # Note: memory['last_view'] must be updated by caller (we update it below)
    # but keep consistent after decision (we update before returning normally).
