                    return (i, j, c)
        return (None, None, None)

    def find_first_in_col3(obj_id):
        for j in range(7):
            c = cell_at(3, j)
            if c[0] == obj_id:
                return (3, j, c)
        return (None, None, None)

    def carrying_key_of_color(col):
        return carried[0] == 5 and carried[1] == col

    def is_pickable(cell):
        return cell[0] in (5, 6, 7)

    def front_allows_forward(cell):
        # allowed forward targets: goal(8), empty(1), floor(3), open door(4 with state 0)
        if cell[0] == 8:
            return True
        if cell[0] in (1, 3):
            return True
        if cell[0] == 4 and cell[2] == 0:
            return True
        return False

    def choose_turn_alternate():
        # Choose a turn action that tries to avoid repeating the same turn as last time.
        if memory.get('last_turn') == 1:
            return 0
        if memory.get('last_turn') == 0:
            return 1
        return 1 if memory['scan_dir'] == 1 else 0

    # --- phase tracking (rooms) ---
    # If goal visible -> final phase
    if find_any(8)[0] is not None:
        memory['phase'] = 6

    nd = find_first_in_col3(4)
    next_door_row = nd[1] if nd[0] is not None else None
    prev_row = memory.get('prev_next_door_row')
    if prev_row is not None:
        if next_door_row is None or (next_door_row is not None and next_door_row > prev_row):
            if memory['phase'] < 6:
                memory['phase'] += 1
    memory['prev_next_door_row'] = next_door_row
    phase = memory['phase']

    # --- core decision logic tuned for observed failure mode ---
    action = None

    # 1) If there's a wall in front, do not forward. Prefer turning away.
    if front[0] == 2:
        # If we've recently attempted forwards that didn't move us or repeatedly hit wall, be more aggressive
        if memory['failed_forwards'] >= 2 or memory['stuck_wall_count'] >= 2:
            # pick opposite of last_turn if known, otherwise alternate
            if memory['last_turn'] == 1:
                action = 0
            elif memory['last_turn'] == 0:
                action = 1
            else:
                action = choose_turn_alternate()
            # also flip scan_dir to try the other direction next time
            memory['scan_dir'] = 1 - memory['scan_dir']
        else:
            # gentle alternate turning
            action = choose_turn_alternate()

    # 2) If front is unseen, turn to scan (prefer scan_dir; flip if repeating)
    elif front[0] == 0:
        if memory['repeat_count'] >= 4:
            memory['scan_dir'] = 1 - memory['scan_dir']
            memory['repeat_count'] = 0
        action = 1 if memory['scan_dir'] == 1 else 0

    # 3) If door in front: handle robustly (only toggle when door present)
    elif front[0] == 4:
        door_state = front[2]  # 0 open, 1 closed, 2 locked
        door_color = front[1]
        if door_state == 0:
            # open door -> move forward unless forwards recently failed
            if memory['failed_forwards'] > 0:
                action = choose_turn_alternate()
            else:
                action = 2
        elif door_state == 1:
            action = 5
        else:  # locked
            if carrying_key_of_color(door_color):
                action = 5
            else:
                # try to face a visible key; otherwise scan
                kcol, krow, _ = find_any(5)
                if kcol is not None:
                    if kcol < 3:
                        action = 0
                    elif kcol > 3:
                        action = 1
                    else:
                        action = choose_turn_alternate()
                else:
                    if memory['repeat_count'] >= 4:
                        memory['scan_dir'] = 1 - memory['scan_dir']
                        memory['repeat_count'] = 0
                    action = 1 if memory['scan_dir'] == 1 else 0

    # 4) Goal directly ahead: go forward
    elif front[0] == 8:
        action = 2

    # 5) Key directly ahead and free hands: pick it
    elif front[0] == 5 and carried[0] == 1:
        action = 3

    # 6) Other pickables: avoid picking unless stuck
    elif front[0] in (6, 7):
        if memory['failed_forwards'] >= 3 and carried[0] == 1:
            action = 3
        else:
            # turn to find alternative path
            action = choose_turn_alternate()

    # 7) Safe forward path: move forward if no evidence that forwards recently failed
    elif front_allows_forward(front):
        if memory['failed_forwards'] > 0:
            # re-orient first to avoid repeatedly failing
            action = choose_turn_alternate()
        else:
            action = 2

    # 8) Fallback: scan/turn, flipping if repeating too much
    else:
        if memory['repeat_count'] >= 4:
            memory['scan_dir'] = 1 - memory['scan_dir']
            memory['repeat_count'] = 0
        action = 1 if memory['scan_dir'] == 1 else 0

    # Safety checks: don't toggle or pick if nothing appropriate in front
    if action == 5 and front[0] != 4:
        action = choose_turn_alternate()
    if action == 3 and not is_pickable(front):
        action = choose_turn_alternate()

    # Update last_view for next step
    memory['last_view'] = vf

    return action
